        if nodeRoot.rightNode and nodeRoot.val != nodeRoot.rightNode.val: return False
        if nodeRoot.leftNode and nodeRoot.val != nodeRoot.leftNode.val: return False
        return self.checkUnivalTree(nodeRoot.rightNode) and self.checkUnivalTree(nodeRoot.leftNode)

